from typing import Protocol, runtime_checkable

@runtime_checkable
class Scorer(Protocol):
    def score(self, text: str) -> float: ...

class LengthScorer:
    def score(self, text):
        return float(len(text))

class VowelScorer:
    def score(self, text):
        return float(sum(ch in "aeiou" for ch in text))

class Rogue:
    pass

def best(candidates, text):
    scorers = [c for c in candidates if isinstance(c, Scorer)]
    winner = max(scorers, key=lambda s: s.score(text))
    return type(winner).__name__

print(best([Rogue(), VowelScorer(), LengthScorer()], "protocols"))
